def pre(xs, k):
    # Contract covers every valid input: list of 0..6 ints in [-9, 9], 0 <= k <= 12.
    if len(xs) > 6:
        return False
    for x in xs:
        if x < -9 or x > 9:
            return False
    if k < 0 or k > 12:
        return False
    return True


def post(xs, k, result):
    n = len(xs)
    # Result must be a list of the same length as xs.
    if len(result) != n:
        return False
    # Empty input yields empty output (covered by the length check above).
    if n == 0:
        return True
    # Element-wise: result[i] == xs[(i + k) % n]
    for i in range(n):
        if result[i] != xs[(i + k) % n]:
            return False
    return True
